//! Prospective high-throughput evidence-surveillance researcher workbench.
//! Atlas feature `AFA-adapter-P01-F19`: a bounded A1 interaction surface over the
//! EvidenceFeed3 copilot that keeps queue capacity and checkpoint state visible.

use std::collections::BTreeSet;
use bioprism_foundation::{AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;
use crate::throughput_evidence_surveillance_research_copilot::{run_throughput_evidence_surveillance_research_copilot, ThroughputEvidenceSurveillanceResearchCopilotRequest, ThroughputResearchCopilotDisposition};

pub const FEATURE_ID: &str = "AFA-adapter-P01-F19";
pub const CONTRACT_VERSION: &str = "adapter-throughput-evidence-surveillance-research-workbench/1.0";
pub const INPUT_SCHEMA: &str = "EvidenceFeed3@1";
pub const OUTPUT_SCHEMA: &str = "QualifiedEvidenceSet5@1";
const VIEWS: [&str; 4] = ["view:queue", "view:capacity", "view:checkpoint", "view:provenance"];
const PANELS: [&str; 4] = ["panel:overflow", "panel:negative", "panel:qualified", "panel:unknown"];

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ThroughputEvidenceSurveillanceResearchWorkbenchRequest { pub copilot_request: ThroughputEvidenceSurveillanceResearchCopilotRequest, pub workbench_id: String, pub scope: String, pub requested_view_order: Vec<String>, pub requested_panel_order: Vec<String>, pub budget_units: u32, pub replay_identity: ContentHash, pub boundary: String }

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ThroughputEvidenceSurveillanceResearchWorkbenchReceipt { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub workbench_id: String, pub scope: String, pub batch_id: String, pub checkpoint_seq: u64, pub capacity: usize, pub disposition: ThroughputResearchCopilotDisposition, pub view_order: Vec<String>, pub panel_order: Vec<String>, pub candidate_order: Vec<String>, pub qualified_order: Vec<String>, pub unknown_order: Vec<String>, pub blocked_order: Vec<String>, pub overflow_order: Vec<String>, pub replay_identity: ContentHash, pub copilot_run_digest: ContentHash, pub workbench_digest: ContentHash, pub queue_digest: ContentHash, pub checkpoint_digest: ContentHash, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_evidence: Vec<String>, pub effect_receipts: Vec<String>, pub artifact: TypedResearchArtifact, pub raw_data_local: bool, pub boundary: String }

#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum ThroughputEvidenceSurveillanceResearchWorkbenchError { #[error("invalid throughput workbench request: {0}")] Invalid(String), #[error("throughput workbench artifact failed: {0}")] Artifact(String), #[error("throughput workbench copilot failed: {0}")] Copilot(String) }

impl ThroughputEvidenceSurveillanceResearchWorkbenchReceipt { pub fn validate(&self)->Result<(),ThroughputEvidenceSurveillanceResearchWorkbenchError>{ if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||self.request_id.trim().is_empty()||self.workbench_id.trim().is_empty()||self.scope.trim().is_empty()||self.batch_id.trim().is_empty()||self.checkpoint_seq==0||self.capacity==0||self.view_order!=VIEWS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>()||self.panel_order!=PANELS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>()||self.candidate_order.is_empty()||self.effect_receipts.is_empty(){return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench identity, checkpoint, canonical views, capacity, locality, candidates, or effects are incomplete".into()))} for values in [&self.candidate_order,&self.qualified_order,&self.unknown_order,&self.blocked_order,&self.overflow_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if values.windows(2).any(|p|p[0]>=p[1]){return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench ordering is not canonical".into()))}} let classified=self.qualified_order.iter().chain(self.unknown_order.iter()).chain(self.blocked_order.iter()).chain(self.overflow_order.iter()).cloned().collect::<BTreeSet<_>>(); if classified!=self.candidate_order.iter().cloned().collect(){return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench states do not partition candidates".into()))} for value in [&self.replay_identity,&self.copilot_run_digest,&self.workbench_digest,&self.queue_digest,&self.checkpoint_digest,&self.artifact.content_hash]{if value.as_str().len()!=64{return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench digest is invalid".into()))}} if self.effect_receipts.iter().any(|e|!e.starts_with("view:throughput-evidence-workbench:")&&e!="block:unsafe-release"){return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench effect is outside read-only gate".into()))} self.artifact.validate_metadata().map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Artifact(e.to_string())) } }

pub fn throughput_evidence_surveillance_research_workbench_manifest()->CapabilityManifest{CapabilityManifest{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),capability_id:FEATURE_ID.into(),version:CONTRACT_VERSION.into(),owner_crate:"adapter".into(),consumers:["AURORA extension developer".into(),"preclinical researcher".into()].into(),behavior:"renders a deterministic prospective high-throughput EvidenceFeed3 workbench with queue, capacity, checkpoint, overflow, negative, unknown, qualified, and provenance panels without external effects".into(),value:"gives extension developers an accessible replayable view of bounded evidence admission while retaining overflow and omission receipts".into(),inputs:vec![TypedPort{name:"throughput_evidence_workbench_request".into(),schema:INPUT_SCHEMA.into(),required:true}],outputs:vec![TypedPort{name:"qualified_throughput_evidence_workbench_set".into(),schema:OUTPUT_SCHEMA.into(),required:true}],effects:[Effect::ReadLocalData,Effect::ExecuteLocalComputation].into(),permissions:["view:authorized-research-state".into()].into(),determinism:Determinism::ByteStable,evidence:vec![EvidenceReference{source_id:"json-schema".into(),state:EvidenceState::Supported,locator:Some("https://json-schema.org/specification".into())}],authority_requirements:Vec::new(),autonomy_tier:AutonomyTier::A1,surfaces:[ResearchSurface::Ui,ResearchSurface::Api,ResearchSurface::Sdk,ResearchSurface::Cli,ResearchSurface::Operator].into(),boundary:PRECLINICAL_BOUNDARY.into()}}

pub fn render_throughput_evidence_surveillance_research_workbench(request:&ThroughputEvidenceSurveillanceResearchWorkbenchRequest)->Result<ThroughputEvidenceSurveillanceResearchWorkbenchReceipt,ThroughputEvidenceSurveillanceResearchWorkbenchError>{validate_request(request)?;let c=run_throughput_evidence_surveillance_research_copilot(&request.copilot_request).map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Copilot(e.to_string()))?;let views=VIEWS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>();let panels=PANELS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>();let candidate=c.candidate_order.clone();let qualified=c.selected_order.clone();let unknown=c.unresolved_order.clone();let blocked=c.denied_order.clone();let overflow=c.overflow_order.clone();let cv=serde_json::to_value(&c).map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Artifact(e.to_string()))?;let copilot_run_digest=ContentHash::of_value(&cv).map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Artifact(e.to_string()))?;let queue_digest=c.queue_digest.clone();let checkpoint_digest=c.checkpoint_digest.clone();let workbench_digest=ContentHash::of_value(&json!({"workbench_id":request.workbench_id,"scope":request.scope,"batch_id":request.copilot_request.batch_id,"checkpoint_seq":request.copilot_request.checkpoint_seq,"capacity":request.copilot_request.capacity,"views":views,"panels":panels,"candidate":candidate,"qualified":qualified,"unknown":unknown,"blocked":blocked,"overflow":overflow,"replay_identity":request.replay_identity,"copilot_run_digest":copilot_run_digest})).map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Artifact(e.to_string()))?;let mut omissions=c.omissions.clone();omissions.push("workbench:read-only-throughput-view".into());omissions.sort();omissions.dedup();let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.copilot_request.request_id,"workbench_id":request.workbench_id,"scope":request.scope,"batch_id":request.copilot_request.batch_id,"checkpoint_seq":request.copilot_request.checkpoint_seq,"capacity":request.copilot_request.capacity,"disposition":c.disposition,"view_order":views,"panel_order":panels,"candidate_order":candidate,"qualified_order":qualified,"unknown_order":unknown,"blocked_order":blocked,"overflow_order":overflow,"replay_identity":request.replay_identity,"copilot_run_digest":copilot_run_digest,"queue_digest":queue_digest,"checkpoint_digest":checkpoint_digest,"omissions":omissions,"uncertainty":c.uncertainty,"negative_evidence":c.negative_evidence,"boundary":PRECLINICAL_BOUNDARY,"raw_data_local":true});let artifact=TypedResearchArtifact::from_payload(format!("adapter-throughput-evidence-workbench:{}",request.workbench_id),"application/vnd.aurora.throughput-evidence-workbench+json",&payload,vec![],vec![]).map_err(|e|ThroughputEvidenceSurveillanceResearchWorkbenchError::Artifact(e.to_string()))?;let receipt=ThroughputEvidenceSurveillanceResearchWorkbenchReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:request.copilot_request.request_id.clone(),workbench_id:request.workbench_id.clone(),scope:request.scope.clone(),batch_id:request.copilot_request.batch_id.clone(),checkpoint_seq:request.copilot_request.checkpoint_seq,capacity:request.copilot_request.capacity,disposition:c.disposition,view_order:views,panel_order:panels,candidate_order:candidate,qualified_order:qualified,unknown_order:unknown,blocked_order:blocked,overflow_order:overflow,replay_identity:request.replay_identity.clone(),copilot_run_digest,workbench_digest,queue_digest,checkpoint_digest,omissions,uncertainty:c.uncertainty.clone(),negative_evidence:c.negative_evidence.clone(),effect_receipts:vec![format!("view:throughput-evidence-workbench:{}",request.workbench_id)],artifact,raw_data_local:true,boundary:request.boundary.clone()};receipt.validate()?;Ok(receipt)}
fn validate_request(r:&ThroughputEvidenceSurveillanceResearchWorkbenchRequest)->Result<(),ThroughputEvidenceSurveillanceResearchWorkbenchError>{if r.workbench_id.trim().is_empty()||r.scope.trim().is_empty()||r.budget_units==0||r.boundary!=PRECLINICAL_BOUNDARY||r.copilot_request.boundary!=PRECLINICAL_BOUNDARY||!r.copilot_request.raw_data_local||!r.copilot_request.dry_run{return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench identity, budget, dry-run, locality, or boundary is invalid".into()))}if r.requested_view_order!=VIEWS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>()||r.requested_panel_order!=PANELS.iter().map(|v|(*v).to_string()).collect::<Vec<_>>()||r.replay_identity.as_str().len()!=64||r.copilot_request.replay_identity.as_str().len()!=64{return Err(ThroughputEvidenceSurveillanceResearchWorkbenchError::Invalid("throughput workbench views, panels, or replay identity is invalid".into()))}Ok(())}

#[cfg(test)]mod tests{use super::*;use crate::throughput_evidence_surveillance_research_copilot::ThroughputCopilotEvidenceObservation;use bioprism_foundation::{EvidenceAvailability,EvidenceState};fn request()->ThroughputEvidenceSurveillanceResearchWorkbenchRequest{let c=ThroughputEvidenceSurveillanceResearchCopilotRequest{request_id:"req-19".into(),agent_id:"extension-19".into(),batch_id:"batch-19".into(),checkpoint_seq:1,capacity:2,declared_tools:vec!["evidence.inspect".into()],requested_tool:"evidence.inspect".into(),max_tool_calls:1,dry_run:true,approval_reference:None,approval_granted:false,observations:vec![ThroughputCopilotEvidenceObservation{source_id:"source-a".into(),sequence:1,digest:Some(ContentHash::of_bytes(b"a")),availability:EvidenceAvailability::Available,evidence_state:EvidenceState::Supported,relevance_score:90,negative_result:false}],min_relevance_score:50,policy_allow:true,protected_closure:true,raw_data_local:true,replay_identity:ContentHash::of_bytes(b"copilot-19"),boundary:PRECLINICAL_BOUNDARY.into()};ThroughputEvidenceSurveillanceResearchWorkbenchRequest{copilot_request:c,workbench_id:"wb-19".into(),scope:"batch:batch-19".into(),requested_view_order:VIEWS.iter().map(|v|(*v).to_string()).collect(),requested_panel_order:PANELS.iter().map(|v|(*v).to_string()).collect(),budget_units:4,replay_identity:ContentHash::of_bytes(b"wb-19"),boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn manifest_is_a1(){assert_eq!(throughput_evidence_surveillance_research_workbench_manifest().autonomy_tier,AutonomyTier::A1)}#[test]fn renders_view(){let r=render_throughput_evidence_surveillance_research_workbench(&request()).unwrap();assert_eq!(r.feature_id,FEATURE_ID)}#[test]fn policy_denial_visible(){let mut r=request();r.copilot_request.policy_allow=false;assert!(render_throughput_evidence_surveillance_research_workbench(&r).is_ok())}#[test]fn rejects_non_dry_run(){let mut r=request();r.copilot_request.dry_run=false;assert!(render_throughput_evidence_surveillance_research_workbench(&r).is_err())}#[test]fn rejects_panels(){let mut r=request();r.requested_panel_order.reverse();assert!(render_throughput_evidence_surveillance_research_workbench(&r).is_err())}#[test]fn replay_stable(){let r=request();assert_eq!(render_throughput_evidence_surveillance_research_workbench(&r).unwrap(),render_throughput_evidence_surveillance_research_workbench(&r).unwrap())}}
